using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class RecruiterWorkspacePage:UserControl{public RecruiterWorkspacePage(){BackColor=Theme.Background;Padding=new Padding(4);var cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=145,WrapContents=true};cards.Controls.Add(Kpi(L.Fa?"درخواست‌های فعال":"Active applications","SELECT COUNT(*) FROM Applications WHERE Stage NOT IN ('Hired','Rejected')"));cards.Controls.Add(Kpi(L.Fa?"مصاحبه‌های ۷ روز آینده":"Interviews next 7 days","SELECT COUNT(*) FROM Interviews WHERE ScheduledAt>=GETDATE() AND ScheduledAt<DATEADD(day,7,GETDATE()) AND Status='Scheduled'"));cards.Controls.Add(Kpi(L.Fa?"پیشنهادهای باز":"Open offers","SELECT COUNT(*) FROM Offers WHERE Status IN ('Draft','Sent','PendingApproval')"));cards.Controls.Add(Kpi(L.Fa?"کارهای باز":"Open tasks","SELECT COUNT(*) FROM RecruitmentTasks WHERE IsCompleted=0 AND (AssignedTo=@u OR AssignedTo IS NULL)"));Controls.Add(cards);var tabs=new TabControl{Dock=DockStyle.Fill};tabs.TabPages.Add(Tab(L.Fa?"اولویت‌های امروز":"Today's priorities","SELECT TOP 30 t.Id,t.Title,t.DueAt,t.Priority,c.FullName AS Candidate,t.IsCompleted FROM RecruitmentTasks t LEFT JOIN Candidates c ON c.Id=t.CandidateId WHERE t.IsCompleted=0 ORDER BY CASE t.Priority WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END,t.DueAt"));tabs.TabPages.Add(Tab(L.Fa?"کاندیداهای برتر":"Top candidates","SELECT TOP 30 c.Id,c.FullName,c.PrimarySkill,c.ExperienceYears,MAX(ISNULL(a.Score,0)) AS BestScore,COUNT(a.Id) AS Applications FROM Candidates c LEFT JOIN Applications a ON a.CandidateId=c.Id GROUP BY c.Id,c.FullName,c.PrimarySkill,c.ExperienceYears ORDER BY BestScore DESC,c.ExperienceYears DESC"));tabs.TabPages.Add(Tab(L.Fa?"مصاحبه‌های پیش رو":"Upcoming interviews","SELECT TOP 30 i.ScheduledAt,c.FullName,j.Title,i.Interviewer,i.Status FROM Interviews i JOIN Applications a ON a.Id=i.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId WHERE i.ScheduledAt>=GETDATE() ORDER BY i.ScheduledAt"));Controls.Add(tabs);tabs.BringToFront();}Panel Kpi(string title,string sql){var p=Ui.Card();p.Size=new Size(240,115);var a=Ui.Label(title,10,true);a.Location=new Point(16,16);var v=Ui.Label(Convert.ToString(Database.Scalar(sql,new System.Data.SqlClient.SqlParameter("@u",AppSession.UserId))),24,true);v.ForeColor=Theme.Primary;v.Location=new Point(16,53);p.Controls.Add(a);p.Controls.Add(v);return p;}TabPage Tab(string title,string sql){var t=new TabPage(title);var g=Ui.Grid();g.DataSource=Database.Query(sql);t.Controls.Add(g);return t;}}}